$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest

$root = (Get-Location).Path
if (-not (Test-Path (Join-Path $root 'pubspec.yaml'))) {
    throw 'Run this script from the almustafa-connect-erp project root.'
}

$utf8 = New-Object System.Text.UTF8Encoding($false)
$stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
$backupRoot = Join-Path (Split-Path $root -Parent) "almustafa-connect-erp_backups/access_control_phase3_$stamp"

function Read-ProjectFile {
    param([Parameter(Mandatory = $true)][string]$RelativePath)
    $path = Join-Path $root $RelativePath

    if (-not (Test-Path $path)) {
        throw "Required file not found: $RelativePath"
    }

    return [IO.File]::ReadAllText($path).Replace("`r`n", "`n")
}

function Write-ProjectFile {
    param(
        [Parameter(Mandatory = $true)][string]$RelativePath,
        [Parameter(Mandatory = $true)][string]$Content
    )

    $path = Join-Path $root $RelativePath
    New-Item -ItemType Directory -Path (Split-Path $path -Parent) -Force | Out-Null
    [IO.File]::WriteAllText($path, $Content, $utf8)
    Write-Host "Created/updated: $RelativePath" -ForegroundColor Green
}

function Backup-ProjectFile {
    param([Parameter(Mandatory = $true)][string]$RelativePath)

    $source = Join-Path $root $RelativePath
    if (-not (Test-Path $source)) { return }

    $destination = Join-Path $backupRoot $RelativePath
    New-Item -ItemType Directory -Path (Split-Path $destination -Parent) -Force | Out-Null
    Copy-Item $source $destination -Force
}

function Add-Import {
    param(
        [Parameter(Mandatory = $true)][string]$Content,
        [Parameter(Mandatory = $true)][string]$ImportLine
    )

    if ($Content.Contains($ImportLine)) { return $Content }

    $matches = [regex]::Matches(
        $Content,
        "(?m)^import\s+['""].+?['""];\s*$"
    )

    if ($matches.Count -eq 0) {
        throw "Import block not found: $ImportLine"
    }

    $last = $matches[$matches.Count - 1]
    return $Content.Insert(
        $last.Index + $last.Length,
        "`n$ImportLine"
    )
}

function Insert-BeforeFirst {
    param(
        [Parameter(Mandatory = $true)][string]$Content,
        [Parameter(Mandatory = $true)][string]$Marker,
        [Parameter(Mandatory = $true)][string[]]$Patterns,
        [Parameter(Mandatory = $true)][string]$Block
    )

    if ($Content.Contains($Marker)) { return $Content }

    foreach ($pattern in $Patterns) {
        $match = [regex]::Match($Content, $pattern)
        if ($match.Success) {
            return $Content.Insert($match.Index, $Block)
        }
    }

    throw "Registration anchor not found: $Marker"
}

$payloads = @{
    'lib/features/access_control/domain/services/access_control_service.dart' = ''
    'lib/features/access_control/data/services/access_control_service_impl.dart' = ''
    'lib/features/access_control/presentation/pages/unauthorized_access_page.dart' = ''
    'lib/features/access_control/presentation/widgets/permission_guard.dart' = ''
    'lib/features/dashboard/presentation/widgets/sidebar.dart' = ''
}
$serviceLocator = 'lib/core/di/service_locator.dart'
$sidebar = 'lib/features/dashboard/presentation/widgets/sidebar.dart'

foreach ($relativePath in (@(
    $serviceLocator,
    $sidebar
) + $payloads.Keys)) {
    Backup-ProjectFile -RelativePath $relativePath
}

foreach ($item in $payloads.GetEnumerator()) {
    $text = [Text.Encoding]::UTF8.GetString(
        [Convert]::FromBase64String($item.Value)
    )

    Write-ProjectFile `
        -RelativePath $item.Key `
        -Content $text
}

$content = Read-ProjectFile -RelativePath $serviceLocator

foreach ($importLine in @(
    "import 'package:firebase_auth/firebase_auth.dart';",
    "import '../../features/access_control/data/services/access_control_service_impl.dart';",
    "import '../../features/access_control/domain/services/access_control_service.dart';"
)) {
    $content = Add-Import `
        -Content $content `
        -ImportLine $importLine
}

if (-not $content.Contains(
    'registerLazySingleton<FirebaseAuth>'
)) {
    $storageAnchor =
        '  sl.registerLazySingleton<FirebaseStorage>('

    $index = $content.IndexOf($storageAnchor)

    if ($index -lt 0) {
        throw 'FirebaseStorage service registration anchor not found.'
    }

    $firebaseAuthRegistration = @'
  sl.registerLazySingleton<FirebaseAuth>(
    () => FirebaseAuth.instance,
  );

'@

    $content = $content.Insert(
        $index,
        $firebaseAuthRegistration
    )
}

$accessRegistration = @'
  sl.registerLazySingleton<AccessControlService>(
    () => AccessControlServiceImpl(
      sl<FirebaseAuth>(),
      sl<UserRoleAssignmentRepository>(),
      sl<AppRoleRepository>(),
    ),
  );

'@

$content = Insert-BeforeFirst `
    -Content $content `
    -Marker 'registerLazySingleton<AccessControlService>' `
    -Patterns @(
        '(?m)^\s*sl\.registerLazySingleton<UserRoleAssignmentRepository>',
        '(?m)^\s*sl\.registerLazySingleton<AppRoleRepository>',
        '(?m)^\s*sl\.registerLazySingleton<ParentPortalRepository>',
        '(?m)^\s*sl\.registerLazySingleton<'
    ) `
    -Block $accessRegistration

Write-ProjectFile `
    -RelativePath $serviceLocator `
    -Content $content

# Sidebar is intentionally replaced as one complete file because every
# menu item now participates in permission filtering and route guarding.
$sidebarText = [Text.Encoding]::UTF8.GetString(
    [Convert]::FromBase64String($payloads[$sidebar])
)
Write-ProjectFile -RelativePath $sidebar -Content $sidebarText

$formatFiles = @(
    $serviceLocator,
    $sidebar
) + $payloads.Keys

Write-Host ''
Write-Host 'Running dart format...' -ForegroundColor Cyan

& dart format $formatFiles

if ($LASTEXITCODE -ne 0) {
    throw 'dart format failed.'
}

Write-Host ''
Write-Host 'Running flutter analyze...' -ForegroundColor Cyan

& flutter analyze

if ($LASTEXITCODE -ne 0) {
    throw 'flutter analyze found issues. Copy the complete output into ChatGPT.'
}

Write-Host ''
Write-Host 'Roles and Permissions Phase 3 enforcement completed successfully.' -ForegroundColor Green
Write-Host 'Sidebar filtering and route guards are now active.' -ForegroundColor Cyan
Write-Host "Backup: $backupRoot" -ForegroundColor DarkGray
